window.AUTH=window.AUTH||{};window.AUTH["19-199"]={"d":"19-199","id":"2020/19-199","n":"Salinas v. United States Railroad Retirement Board","briefs":[{"k":"petitioner","label":"Brief of petitioner Manfredo Salinas","date":"2020-03-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-199/139527/20200331124815574_Salinas%20Merits%20Brief%20-%203.30%20FINAL.pdf","side":"pet","n":49},{"k":"respondent","label":"Brief of respondent United States Railroad Retirement Board","date":"2020-06-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-199/145162/20200608161534224_19-199bsUnitedStates.pdf","side":"res","n":77},{"k":"reply","label":"Reply of petitioner Manfredo Salinas","date":"2020-07-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-199/147205/20200708114850218_19-199%20-%20Salinas%20v.%20RRB%20-%20Reply.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-199_o7jq.pdf","tr":true,"items":[{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Abbruzzese v. R.R. Ret. Bd.","cite":"63 F.3d 972","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/63/972/","op":2,"by":{"0":"40","1":"48"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"op":7,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Alton R.R. Co. v. R.R. Ret. Bd.","cite":"16 F. Supp. 955","y":1936,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./16/955/","by":{"0":"5"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"0":"31","2":"13"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"op":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"23","1":"33"}},{"t":"case","label":"BNSF Ry. Co. v. Loos","cite":"139 S. Ct. 893","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6","1":"20"}},{"t":"case","label":"Bowen v. Mich. Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25, 39, 41","1":"41, 42"}},{"t":"case","label":"Burke v. R.R. Ret. Bd.","cite":"165 F.2d 24","y":1947,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/165/24/","by":{"0":"37"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"op":9,"ar":6,"sum":"Explaining that §405(g) “clearly limits judicial review to a particular type of agency action”.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"4, 8, 11, 20"}},{"t":"case","label":"Cunningham v. R.R. Ret. Bd.","cite":"392 F.3d 567","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/392/567/","op":1,"by":{"0":"30, 40, 43","1":"48"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"25","1":"42"}},{"t":"case","label":"Denberg v. R.R. Ret. Bd.","cite":"696 F.2d 1193","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/696/1193/","by":{"0":"9, 38"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"0":"20"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43"}},{"t":"case","label":"Harris v. R.R. Ret. Bd.","cite":"198 F.3d 139","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/139/","op":2,"by":{"0":"30, 40","1":"48"}},{"t":"case","label":"Hisquierdo v. Hisquierdo","cite":"439 U.S. 572","y":1979,"id":"1978/77-533","sc":1,"sum":"Benefits payable under the Act may not be divided under the community property law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Intel Corp. Inv. Policy Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Johnson v. R.R. Ret. Bd.","cite":"925 F.2d 1374","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/925/1374/","by":{"0":"36"}},{"t":"case","label":"King v. R.R. Ret. Bd.","cite":"981 F.2d 365","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/365/","by":{"0":"37"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"op":1,"ar":2,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"24","1":"37","2":"8, 20, 21, 23"}},{"t":"case","label":"Lindahl v. Office of Pers. Mgmt.","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Lockhart v. United States","cite":"136 S. Ct. 958","y":2016,"id":"2015/14-8358","sc":1,"sum":"The Court determined that a prior conviction of “aggravated sexual abuse” or “sexual abuse” may trigger a mandatory minimum sentence, even when the prior conviction did not involve a minor.","sumSrc":"Oyez","by":{"0":"31, 32","1":"24, 25"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 489","y":2015,"url":"https://supreme.justia.com/cases/federal/us/575/489/","sc":1,"op":1,"by":{"0":"24, 25, 41"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 602","y":1926,"id":"1900-1940/272us52","sc":1,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Pub. Citizen v. U.S. Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"R.R. Ret. Bd. v. Alton R. Co.","cite":"295 U.S. 330","y":1935,"id":"scdb/1934-051","sc":1,"sum":"1. The power of Congress to regulate interstate commerce is subject to the guaranty of due process in the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"sum":"The Court held that the reaudit rule is a reasonable interpretation of the GME Amendment and that it is not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Roberts v. U.S. R.R. Ret. Bd.","cite":"346 F.3d 139","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/346/139/","op":3,"by":{"0":"14, 30, 40, 43","1":"11, 12, 48"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Salinas v. U.S. R.R. Ret. Bd.","cite":"765 F. App’x 79","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/765/79/","by":{"0":"1"}},{"t":"case","label":"Scott v. R.R. Ret. Bd.","cite":"631 F.3d 359","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/631/359/","by":{"0":"37"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"op":1,"ar":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"30, 36, 38","2":"3, 4, 8"}},{"t":"case","label":"Steebe v. R.R. Ret. Bd.","cite":"708 F.2d 250","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/708/250/","op":1,"by":{"0":"9, 30, 38, 40","1":"48"}},{"t":"case","label":"Stovic v. R.R. Ret. Bd.","cite":"826 F.3d 500","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/826/500/","op":2,"by":{"0":"passim","1":"48","2":"9, 10, 11, 12"}},{"t":"case","label":"Szostak v. R.R. Ret. Bd.","cite":"370 F.2d 253","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/370/253/","op":2,"sum":"Interpreting §231g’s predecessor provision.","sumSrc":"opinion","by":{"0":"9","1":"48"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1807/","sc":1,"sum":"Finding standalone jurisdictional determinations immediately reviewable notwithstanding possible later review within a broader decision.","sumSrc":"brief:2","by":{"0":"passim","2":"3, 22"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"19"}},{"t":"reg","label":"20 C.F.R. § 210.7","url":"https://www.ecfr.gov/current/title-20/section-210.7","by":{"0":"36"}},{"t":"reg","label":"60 Fed. Reg. 66,203","url":"https://www.govinfo.gov/link/fr/60/66203","by":{"0":"9","2":"23"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(1)(E)"],"by":{"0":"29, 38"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"35 U.S.C. § 314","url":"https://www.law.cornell.edu/uscode/text/35/314","subs":["(d)"],"by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)","(g)(1976)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"40, 41, 42","1":"12, 20","2":"11, 12"}},{"t":"usc","label":"45 U.S.C. § 231a","url":"https://www.law.cornell.edu/uscode/text/45/231a","subs":["(a)(1)","(a)","(a)(1)(i)","(a)(1)(v)"],"stext":{"head":"§231a. Annuity eligibility requirements","paras":[[0,"(a) Individuals eligible for annuities; disability standards; proof of continued disability"],[0,"(1) The following-described individuals, if they shall have completed ten years of service (or, for purposes of paragraphs (i), (iii), and (v), five years of service, all of which accrues after December 31, 1995) and shall have filed application for annuities, shall, subject to the conditions set forth in subsections (e), (f), and (h), be entitled to annuities in the amounts provided under section 231b of this title—"],[1,"(i) individuals who have attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]);"],[1,"(ii) individuals who have attained the age of sixty and have completed thirty years of service;"],[1,"(iii) individuals who have attained the age of sixty-two and have completed less than thirty years of service, but the annuity of such individuals shall be reduced by 1/180 for each of the first 36 months that he or she is under retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]) when the annuity begins to accrue and by 1/240 for each additional month that he or she is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue;"],[1,"(iv) individuals who have a current connection with the railroad industry, whose permanent physical or mental condition is such as to be disabling for work in their regular occupation, and who (A) have completed twenty years of service or (B) have attained the age of sixty; and"],[1,"(v) individuals whose permanent physical or mental condition is such that they are unable to engage in any regular employment."],[0,"(2) For the purposes of paragraph (iv) of subdivision (1), the Board, with the cooperation of employers and employees, shall secure the establishment of standards determining the physical and mental conditions which permanently disqualify employees for work in the several occupations in the railroad industry, and the Board, employers, and employees shall cooperate in the promotion of the greatest practicable degree of uniformity in the standards applied by the several employers. An individual's condition shall be deemed to be disabling for work in his regular occupation if he will have been disqualified by his employer for service in his regular occupation in accordance with the applicable standards so established; if the employee will not have been so disqualified by his employer, the Board shall determine whether his condition is disabling for work in his regular occupation in accordance with the standards generally established; and, if the employee's regular occupation is not one with respect to which standards will have been established, the standards relating to a reasonably comparable occupation shall be used. If there is no such comparable occupation, the Board shall determine whether the employee's condition is disabling for work in his regular occupation by determining whether under the practices generally prevailing in industries in which such occupation exists such condition is a permanent disqualification for work in such occupation. For purposes of this subdivision and paragraph (iv) of subdivision (1), an employee's \"regular occupation\" shall be deemed to be the occupation in which he will have been engaged in more calendar months than the calendar months in which he will have been engaged in any other occupation during the last preceding five calendar years, whether or not consecutive, in each of which years he will have earned wages or salary, except that, if an employee establishes that during the last fifteen consecutive calendar years he will have been engaged in another occupation in one-half or more of all the months in which he will have earned wages or salary, he may claim such other occupation as his regular occupation."],[0,"(3) Such satisfactory proof shall be made from time to time as prescribed by the Board, of the disability provided for in paragraph (iv) or (v) of subdivision (1) and of the continuance of such disability (according to the standards applied in the establishment of such disability) until the employee attains retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]). If the individual fails to comply with the requirements prescribed by the Board as to proof of the continuance of the disability until he attains retirement age (as defined in section 216(l) of the Social Security Act), his right to an annuity by reason of such disability shall, except for good cause shown to the Board, cease, but without prejudice to his rights to any subsequent annuity to which he may be entitled."],[0,"(4) An individual who is entitled to an annuity under paragraph (v) of subdivision (1), but who does not have at least ten years of service, shall, prior to the month in which the individual attains age 62, be entitled only to an annuity amount computed under section 231b(a) of this title (without regard to section 231b(a)(2) of this title) or section 231b(f)(3) of this title. Upon attainment of age 62, such an individual may also be entitled to an annuity amount computed under section 231b(b) of this title, but such annuity amount shall be reduced for early retirement in the same manner as if the individual were entitled to an annuity under subsection (a)(1)(iii)."],[0,"(b) Individuals eligible for supplemental annuities"],[0,"An individual who—"],[1,"(i) has attained age 60 and completed thirty years of service or attained age 65;"],[1,"(ii) has completed twenty-five years of service;"],[1,"(iii) is entitled to the payment of an annuity under subsection (a)(1);"],[1,"(iv) had a current connection with the railroad industry at the time such annuity began to accrue; and"],[1,"(v) has performed compensated service in at least one month prior to October 1, 1981;"],[0,"shall, subject to the conditions set forth in subsections (e) and (h), be entitled to a supplemental annuity in the amount provided under section 231b of this title: Provided, however, That in cases where an individual's annuity under subsection (a)(1) begins to accrue on other than the first day of the month, the amount of any supplemental annuity to which he is entitled for that month shall be reduced by one-thirtieth for each day with respect to which he is not entitled to an annuity under subsection (a)(1)."],[0,"(c) Spouses eligible for annuities"],[0,"(1) The spouse of an individual, if—"],[1,"(i) such individual (A) is entitled to an annuity under subsection (a)(1) and (B) has attained the age of 60 and has completed thirty years of service or has attained the age of 62, and"],[1,"(ii) such spouse (A) has attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]), or (B) has attained the age of 60 and such individual has completed thirty years of service, or (C), in the case of a wife, has in her care (individually or jointly with her husband) a child who meets the qualifications prescribed in paragraph (iii) of subsection (d)(1) (without regard to the provisions of clause (B) of such paragraph),"],[0,"shall, subject to the conditions set forth in subsections (e), (f), and (h), be entitled to a spouse's annuity, if he or she has filed application therefor, in the amount provided under section 231c of this title."],[0,"(2) A spouse who would be entitled to an annuity under subdivision (1) or a divorced wife who would be entitled to an annuity under subdivision (4) if he or she had attained retirement age (as defined in section 216(l) of the Social Security Act [42 U.S.C. 416(l)]) may elect upon or after attaining the age of 62 to receive such annuity, but the annuity in any such case shall be reduced by 1/144 for each of the first 36 months that the spouse or divorced wife is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue and by 1/240 for each additional month that the spouse or divorced wife is under retirement age (as defined in section 216(l) of the Social Security Act) when the annuity begins to accrue, except that the annuity of a divorced wife who was previously entitled to a spouse annuity which was reduced under this subdivision shall be reduced by the same percentage as was applicable to the spouse annuity."],[0,"(3) For the purposes of this subchapter, the term \"spouse\" shall mean the wife or husband of an annuitant under subsection (a)(1) who (i) was married to such annuitant for a period of not less than one year immediately preceding the day on which the application for a spouse's annuity is filed, or in the month prior to his or her marriage to such annuitant was eligible for an annuity under paragraph (i) or (iv) of subsection (d)(1) or, on the basis of disability, under paragraph (iii) thereof, or is the parent of such annuitant's son or daughter; and (ii) in the case of a husband, was receiving at least one-half of his support from his wife at the time his wife's annuity under subsection (a)(1) began."],[0,"(4) The \"divorced wife\" (as defined in section 216(d) of the Social Security Act [42 U.S.C. 416(d)]) of an individual, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§231a. Annuity eligibility requirements","tname":"Railroads","by":{"0":"7","1":"3, 4, 3, 3, 3"}},{"t":"law","label":"Pub. L. No. 93-455","url":"https://www.govinfo.gov/link/statute/88/1305","by":{"0":"5"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"op":1,"sum":"Explaining that the presumption is “overcome. . . whenever the congressional intent to preclude judicial review is fairly discernible in the statutory scheme” (internal quotation marks omitted).","sumSrc":"opinion","by":{"1":"42"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":3,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"sum":"Justice Anthony Kennedy, joined by four other Justices, stated that an alien has two options in such a case: he may abide by the terms of the voluntary departure and leave the country on time, maintaining the re-entry perks, or withdraw the voluntary departure request and remain in the country to pursue the motion to reopen. If the alien chooses the second option, he may become subject to deportation proceedings.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Elgin v. Department of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Federal Mar. Comm’n v. Seatrain Lines, Inc.","cite":"411 U.S. 726","y":1973,"id":"1972/71-1647","sc":1,"sum":"In enacting § 15 of the Shipping Act, 1916, Congress conferred on the Federal Maritime Commission (FMC) the power to exempt 'from the antitrust laws agreements, or those portions of agreements, between carriers that create an ongoing arrangement in which both parties undertake continuing responsibilities, and which therefore necessitate continuous FMC supervision, but not onetime acquisition-of-assets agreements …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"op":2,"ar":4,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36, 42","2":"8, 21"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"op":3,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"1":"41, 43"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"1":"18, 25, 26, 27","2":"14, 15"}},{"t":"case","label":"Porto Rico Ry., Light & Power Co. v. Mor","cite":"253 U.S. 345","y":1920,"id":"scdb/1919-067","sc":1,"sum":"In the provision of the Act of March 2, 1917, c. 145, 39 Stat. 965, which gives the United States District Court for Porto Rico jurisdiction “where all the parties on either side of the controversy are citizens or subjects of a foreign State or States, or citizens of a State, Territory, or District of the United States not domiciled in Porto Rico,” etc., the clause “not domiciled in Porto Rico” relates to both …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"SEC v. Louisiana Pub. Serv. Comm’n","cite":"353 U.S. 368","y":1957,"id":"1956/466","sc":1,"sum":"The orders of the Securities and Exchange Commission made judicially reviewable by the last two sentences of § 11 (b) of the Public Utility Holding Company Act of 1935 are the directory orders mentioned in, and authorized by, subsection (b) of § 11 of the Act, and orders which may \"revoke and modify\" any such order previously made under that subsection; and the language referred to does not include an order merely …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32","2":"5"}},{"t":"case","label":"Sones v. United States R.R. Ret. Bd.","cite":"933 F.2d 636","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/933/636/","by":{"1":"48"}},{"t":"case","label":"Taylor v. United States","cite":"136 S. Ct. 2074","y":2016,"id":"2015/14-6166","sc":1,"sum":"The Court determined that, in a prosecution for robbery under the Hobbs Act, the commerce element is satisfied when the government shows that the defendant robbed a drug dealer of drugs or drug proceeds.","sumSrc":"Oyez","by":{"1":"18","2":"15"}},{"t":"case","label":"Thryv, Inc. v. Click-to-Call Techs., LP","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"sum":"The Court held that 35 U.S.C. §314(d) precludes judicial review of a Patent Trial and Appeal Board’s decision to institute inter partes review upon finding that §315(b)’s time bar did not apply.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"United States v. Standard Brewery, Inc.","cite":"251 U.S. 210","y":1920,"id":"scdb/1919-173","sc":1,"sum":"The War-Time Prohibition Act prohibits the use of grains, fruits, and other food products in the.manufacture of “beer, wine, or other intoxicating malt or vinous liquor for beverage purposes,” until the conclusion of the present, war, etc. Held, that the word “intoxicating” qualifies the terms preceding, thus excluding'from the prohibition beer which is not in fact intoxicating.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26","2":"15"}},{"t":"case","label":"United States v. United Verde Copper Co.","cite":"196 U.S. 207","y":1905,"id":"scdb/1904-162","sc":1,"sum":"An apt and sensibl meaning must be given to words as they are used in a statute and the association of words must be regarded as designed and not as accidental, ncSiwill a word be considered an intruder if the statute can be construed reasonably without liminating that word.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"1":"33, 38"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Your Home Visiting Nurse Servs., Inc. v. Shalala","cite":"525 U.S. 449","y":1999,"id":"1998/97-1489","sc":1,"op":10,"ar":31,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the Board does not have jurisdiction to review a fiscal intermediary's refusal to reopen a reimbursement determination. Moreover, the Court held that the federal-question statute and mandamus statute do not entitle Your Home Visiting Nurse to judicial review of the intermediary's reopening decision.","sumSrc":"Oyez","by":{"1":"passim","2":"4, 5, 8, 20"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"1":"33","2":"8, 20"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"1":"33"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"1":"38"}},{"t":"usc","label":"45 U.S.C. § 228k","url":"https://www.law.cornell.edu/uscode/text/45/228k","subs":["(1940)"],"by":{"1":"47, 48"}},{"t":"usc","label":"45 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/45/231","stext":{"head":"§231. Definitions","paras":[[0,"For the purposes of this subchapter—"],[0,"(a)(1) The term \"employer\" shall include—"],[1,"(i) any carrier by railroad subject to the jurisdiction of the Surface Transportation Board under part A of subtitle IV of title 49;"],[1,"(ii) any company which is directly or indirectly owned or controlled by, or under common control with, one or more employers as defined in paragraph (i) of this subdivision, and which operates any equipment or facility or performs any service (except trucking service, casual service, and the casual operation of equipment or facilities) in connection with the transportation of passengers or property by railroad, or the receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, or handling of property transported by railroad;"],[1,"(iii) any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the property or operating all or any part of the business of any employer as defined in paragraph (i) or (ii) of this subdivision;"],[1,"(iv) any railroad association, traffic association, tariff bureau, demurrage bureau, weighing and inspection bureau, collection agency and any other association, bureau, agency, or organization which is controlled and maintained wholly or principally by two or more employers as defined in paragraph (i), (ii), or (iii) of this subdivision and which is engaged in the performance of services in connection with or incidental to railroad transportation; and"],[1,"(v) any railway labor organization, national in scope, which has been or may be organized in accordance with the provisions of the Railway Labor Act, as amended [45 U.S.C. 151 et seq.], and its State and National legislative committees, general committees, insurance departments, and local lodges and divisions, established pursuant to the constitution or bylaws of such organization."],[0,"(2) Notwithstanding the provisions of subdivision (1) of this subsection, the term \"employer\" shall not include—"],[1,"(i) any company by reason of its being engaged in the mining of coal, the supplying of coal to an employer where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities, and"],[1,"(ii) any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general diesel-railroad system of transportation, but shall not exclude any part of the general diesel-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is hereby authorized and directed upon request of the Railroad Retirement Board, or upon complaint of any party interested, to determine after hearing whether any line operated by electric power falls within the terms of this paragraph."],[0,"(b)(1) The term \"employee\" means (i) any individual in the service of one or more employers for compensation, (ii) any individual who is in the employment relation to one or more employers, and (iii) an employee representative: Provided, however, That the term \"employee\" shall include an employee of a local lodge or division defined as an employer in subsection (a) only if he was in the service of or in the employment relation to an employer as defined in paragraph (i) of subsection (a)(1) on or after August 29, 1935."],[0,"(2) The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"(c) The term \"employee representative\" means any officer or official representative of a railway labor organization other than a labor organization included in the term \"employer\" as defined in subsection (a) who before or after August 29, 1935, was in the service of an employer as defined in subsection (a) and who is duly authorized and designated to represent employees in accordance with the Railway Labor Act, as amended [45 U.S.C. 151 et seq.], and any individual who is regularly assigned to or regularly employed by such officer or official representative in connection with the duties of his office."],[0,"(d)(1) An individual is in the service of an employer whether his service is rendered within or without the United States if—"],[1,"(i)(A) he is subject to the continuing authority of the employer to supervise and direct the manner of rendition of his service, or (B) he is rendering professional or technical services and is integrated into the staff of the employer, or (C) he is rendering, on the property used in the employer's operations, personal services the rendition of which is integrated into the employer's operations; and"],[1,"(ii) he renders such service for compensation, or a method of computing the monthly compensation for such service is provided in section 231b(j) of this title."],[0,"(2) Notwithstanding the provisions of subdivision (1) of this subsection—"],[1,"(i) an individual shall be deemed to be in the service of an employer, other than a local lodge or division or a general committee of a railway-labor-organization employer, not conducting the principal part of its business in the United States only when he is rendering service to it in the United States;"],[1,"(ii) an individual shall be deemed to be in the service of a local lodge or division of a railway-labor-organization employer not conducting the principal part of its business in the United States only if (A) all, or substantially all, the individuals constituting the membership of such local lodge or division are employees of an employer conducting the principal part of its business in the United States; or (B) the headquarters of such local lodge or division is located in the United States; and"],[1,"(iii) an individual shall be deemed to be in the service of a general committee of a railway-labor-organization employer not conducting the principal part of its business in the United States only if (A) he is representing a local lodge or division described in clause (A) or (B) of paragraph (ii); or (B) all, or substantially all, the individuals represented by such general committee are employees of an employer conducting the principal part of its business in the United States; or (C) he acts in the capacity of a general chairman or an assistant general chairman of a general committee which represents individuals rendering service in the United States to an employer, but in such case if his office or headquarters is not located in the United States and the individuals represented by such general committee are employees of an employer not conducting the principal part of its business in the United States only such proportion of the remuneration for such service shall be regarded as compensation as the proportion which the mileage in the United States under the jurisdiction of such general committee bears to the total mileage under its jurisdiction, unless such mileage formula is inapplicable, in which case the Board may prescribe such other formula as it finds to be equitable, and if the application of such mileage formula, or such other formula as the Board may prescribe, would result in the compensation of the individual being less than 10 per centum of his remuneration for such service no part of such remuneration shall be regarded as compensation."],[0,"(3) Notwithstanding the provisions of subdivisions (1) and (2) of this subsection, an individual not a citizen or resident of the United States shall not be deemed to be in the service of an employer when rendering service outside the United States to an employer who is required under the laws applicable in the place where the service is rendered to employ therein, in whole or in part, citizens or residents thereof. For purposes of this subdivision, the laws applicable on August 29, 1935, in the place where the service is rendered shall be deemed to have been applicable there at all times prior to that date."],[0,"(e)(1) An individual shall be deemed to have been in the employment relation to an employer on August 29, 1935, if—"],[1,"(i) he was on that date on leave of absence from his employment, expressly granted to him by the employer by whom he was employed, or by a duly authorized representative of such employer, and the grant of such leave of absence will have been established to the satisfaction of the Board before July 1947;"],[1,"(ii) he was in the service of an employer after August 29, 1935, and before January 1946 in each of six calendar months, whether or not consecutive;"],[1,"(iii) before August 29, 1935, he did not retire and was not retired or discharged from the service of the last employer by whom he was employed or its corporate or operating successor, but (A) solely by reason of his physical or mental disability he ceased before August 29, 1935, to be in the service of such employer and thereafter remained continuously disabled until he attained age sixty-five or until August 1945, or (B) solely for such last stated reason an employer by whom he was employed before August 29, 1935, or an employer who is its successor did not on or after August 29, 1935, and before August 1945 call him to return to service, or (C) if he was so called he was solely for such reason unable to render service in six calendar months as provided in paragraph (ii); or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§231. Definitions","tname":"Railroads","by":{"1":"2"}},{"t":"usc","label":"45 U.S.C. § 231f","url":"https://www.law.cornell.edu/uscode/text/45/231f","subs":["(a)","(b)(3)","(b)(5)","(b)(1)"],"stext":{"head":"§231f. Railroad Retirement Board","paras":[[0,"(a) Administration"],[0,"This subchapter shall be administered by the Railroad Retirement Board established by the Railroad Retirement Act of 1937 [45 U.S.C. 228a et seq.] as an independent agency in the executive branch of the Government and composed of three members appointed by the President, by and with the advice and consent of the Senate. Each member shall hold office for a term of five years, except that any member appointed to fill a vacancy occurring prior to the expiration of the term for which his predecessor was appointed shall be appointed for the remainder of the term and any member holding office pursuant to appointment under the Railroad Retirement Act of 1937 when this subchapter becomes effective shall hold office until the term for which he was appointed under such Railroad Retirement Act of 1937 expires. One member shall be appointed from recommendations made by representatives of the employees and one member shall be appointed from recommendations made by representatives of employers as defined in paragraph (i) of section 231(a)(1) of this title, in both cases as the President shall direct, so as to provide representation on the Board satisfactory to the largest number, respectively, of employees and employers concerned. One member, who shall be the chairman of the Board, shall be appointed without recommendation by either employers or employees and shall not be in the employment of or be pecuniarily or otherwise interested in any employer or organization of employees. Vacancies in the Board shall not impair the powers or affect the duties of the Board or of the remaining members of the Board, of whom a majority of those in office shall constitute a quorum for the transaction of business. Upon the expiration of his term of office a member shall continue to serve until his successor is appointed and shall have qualified."],[0,"(b) Powers and duties"],[0,"(1) The Board shall have and exercise all the duties and powers necessary to administer this subchapter. The Board shall take such steps as may be necessary to enforce such subchapter and make awards and certify payments. Decisions by the Board upon issues of law and fact relating to annuities or death benefits shall not be subject to review by any other administrative or accounting officer, agent, or employee of the United States."],[0,"(2) In the case of—"],[1,"(A) an individual who will have completed ten years of service (or five or more years of service, all of which accrues after December 31, 1995) creditable under this subchapter,"],[1,"(B) the wife or divorced wife or husband of such an individual,"],[1,"(C) any survivor of such an individual if such survivor is entitled, or could upon application become entitled, to an annuity under section 231a of this title, and"],[1,"(D) any other person entitled to benefits under title II of the Social Security Act [42 U.S.C. 401 et seq.] on the basis of the wages and self-employment income of such an individual (except a survivor of such an individual where such individual did not have a current connection with the railroad industry at the time of his death);"],[0,"the Board shall provide for the payment on behalf of the Managing Trustee of the Federal Old-Age and Survivors Insurance Trust Fund and the Federal Disability Insurance Trust Fund of monthly benefits payable under title II of the Social Security Act [42 U.S.C. 401 et seq.] which are certified by the Secretary to it for payment under the provisions of title II of the Social Security Act."],[0,"(3) If the Board finds that an applicant is entitled to an annuity or death benefit under the provisions of this subchapter then the Board shall make an award fixing the amount of the annuity or benefit, as the case may be, and shall certify the payment thereof as hereinafter provided; otherwise the application shall be denied. For purposes of this section, the Board shall have and exercise such of the powers, duties and remedies provided in subsections (a), (b), (d), and (n) of section 12 of the Railroad Unemployment Insurance Act [45 U.S.C. 362] as are not inconsistent with the express provisions of this subchapter. The Board is authorized to delegate to any member, officer, or employee of the Board any of the powers conferred upon the Board by this subchapter, excluding only the power to prescribe rules and regulations, including the power to make decisions on applications for annuities or other benefits: Provided, however, That any person aggrieved by a decision on his application for an annuity or other benefit shall have the right to appeal to the Board. Notice of a decision of the Board, or of an employee thereof, shall be communicated to the applicant in writing within thirty days after such decision shall have been made."],[0,"(4)(A) The Secretary of the Treasury shall serve as the disbursing agent for benefits payable under this subchapter, under such rules and regulations as the Secretary may in the Secretary's discretion prescribe."],[0,"(B) The Board shall from time to time certify—"],[1,"(i) to the Secretary of the Treasury the amounts required to be transferred from the Social Security Equivalent Benefit Account and the Dual Benefits Payments Account to the disbursing agent to make payments of benefits and the Secretary of the Treasury shall transfer those amounts;"],[1,"(ii) to the Board of Trustees of the National Railroad Retirement Investment Trust the amounts required to be transferred from the National Railroad Retirement Investment Trust to the disbursing agent to make payments of benefits and the Board of Trustees shall transfer those amounts; and"],[1,"(iii) to the disbursing agent the name and address of each individual entitled to receive a payment, the amount of such payment, and the time at which the payment should be made."],[0,"(5) The Board shall establish and promulgate rules and regulations to provide for the adjustment of all controversial matters arising in the administration of this subchapter. All rules, regulations, or decisions of the Board shall require the approval of at least two members, and they shall be entered upon the records of the Board, which shall be a public record."],[0,"(6) The Board shall gather, keep, compile, and publish in convenient form such records and data as may be necessary to assure proper administration of this subchapter, including subdivision (2) of this subsection. The Board shall have power to require all employers and employees and any officer, board, commission, or other agency of the United States to furnish such information and records as shall be necessary for the administration of this subchapter, including subdivision (2) of this subsection. The several district courts of the United States shall have jurisdiction upon suit by the Board to compel obedience to any order of the Board issued pursuant to this section. The orders, writs, and processes of the United States District Court for the District of Columbia in such suits may run and be served anywhere in the United States. Witnesses summoned before the Board shall be paid the same fees and mileage that are paid witnesses in the district courts of the United States. The Board shall make an annual report to the President of the United States to be submitted to Congress."],[0,"(7) Notwithstanding any other provision of law, the Secretary of Health and Human Services shall furnish the Board certified reports of wages, self-employment income, and periods of service and of other records in his possession, or which he may secure, pertinent to the administration of this subchapter, the Railroad Unemployment Insurance Act [45 U.S.C. 351 et seq.],,1 the Milwaukee Railroad Restructuring Act [45 U.S.C. 901 et seq.], and the Rock Island Railroad Transition and Employee Assistance Act [45 U.S.C. 1001 et seq.]..1 The Board shall furnish the Secretary of Health and Human Services certified reports of records of compensation and periods of service reported to it pursuant to section 231h of this title, of determinations under section 231a of this title, and of other records in its possession, or which it may secure, pertinent to subsection (c) of this section or to the administration of the Social Security Act [42 U.S.C. 301 et seq.] as affected by section 231q of this title. Such certified reports shall be conclusive in adjudication as to the matters covered therein: Provided, however, That if the Board or the Secretary of Health and Human Services receives evidence inconsistent with a certified report and the application involved is still in course of adjudication or otherwise open for such evidence such recertification of such report shall be made as, in the judgment of the Board or the Secretary of Health and Human Services, whichever made the original certification, the evidence warrants. Such recertification and any subsequent recertification shall be treated in the same manner and be subject to the same conditions as an original certification."],[0,"(8) Any department or agency of the United States maintaining records of military service, at the request of the Board, shall certify to the Board, with respect to any individual, the number of months of military service which such department or agency finds the individual to have had during any period or periods with respect to which the Board's request is made, the date and manner of entry into such military service, and the conditions under which such service was continued. Any department or agency of the United States which is authorized to make awards of pensions, disability compensation, or any other gratuitous benefits or allowances payable, on the periodic basis or otherwise, under any other Act of Congress on the basis of military service, at the request of the Board, shall certify to the Board, with respect to any individual, the calendar months for all or part of which any such pension, compensation, benefit, or allowance is payable to, or with respect to, the individual, the amounts of any such pension, compensation, benefit, or allowance, and the military service on which such pension, compensation, benefit, or allowance is based. Any certification made pursuant to the provisions of this subdivision shall be conclusive on the Board: Provided, however, That if evidence inconsistent with any such certification is submitted, and the claim is in the course of adjudication or is otherwise open for such evidence, the Board shall refer such evidence to the department or agency which made the original certification and such department or agency shall make such recertification as in its judgment the evidence warrants. Such recertification, and any subsequent recertification, shall be conclusive, made in the same manner, and subject to the same conditions as an original certification."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231f?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§231f. Railroad Retirement Board","tname":"Railroads","by":{"1":"3, 4, 3, 4, 45","2":"19"}},{"t":"usc","label":"45 U.S.C. § 231g","url":"https://www.law.cornell.edu/uscode/text/45/231g","stext":{"head":"§231g. Court jurisdiction","paras":[[0,"Decisions of the Board determining the rights or liabilities of any person under this subchapter shall be subject to judicial review in the same manner, subject to the same limitations, and all provisions of law shall apply in the same manner as though the decision were a determination of corresponding rights or liabilities under the Railroad Unemployment Insurance Act [45 U.S.C. 351 et seq.] except that the time within which proceedings for the review of a decision with respect to an annuity, supplemental annuity, or lump-sum benefit may be commenced shall be one year after the decision will have been entered upon the records of the Board and communicated to the claimant."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231g?type=usc&year=mostrecent&link-type=html"},"op":16,"ar":4,"head":"§231g. Court jurisdiction","tname":"Railroads","by":{"1":"45"}},{"t":"usc","label":"45 U.S.C. § 231h","url":"https://www.law.cornell.edu/uscode/text/45/231h","by":{"1":"45"}},{"t":"usc","label":"45 U.S.C. § 351","url":"https://www.law.cornell.edu/uscode/text/45/351","subs":["(n)"],"stext":{"head":"§351. Definitions","paras":[[0,"For the purposes of this chapter, except when used in amending the provisions of other Acts—"],[0,"(a) The term \"employer\" means any carrier (as defined in subsection (b) of this section), and any company which is directly or indirectly owned or controlled by one or more such carriers or under common control therewith, and which operates any equipment or facility or performs any service (except trucking service, casual service, and the casual operation of equipment or facilities) in connection with the transportation of passengers or property by railroad, or the receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, or handling of property transported by railroad, and any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the property or operating all or any part of the business of any such employer: Provided, however, That the term \"employer\" shall not include any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general steam-railroad system of transportation, but shall not exclude any part of the general steam-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is hereby authorized and directed upon request of the Railroad Retirement Board, or upon complaint of any party interested, to determine after hearing whether any line operated by electric power falls within the terms of this proviso. The term \"employer\" shall also include railroad associations, traffic associations, tariff bureaus, demurrage bureaus, weighing and inspection bureaus, collection agencies, and other associations, bureaus, agencies, or organizations controlled and maintained wholly or principally by two or more employers as hereinbefore defined and engaged in the performance of services in connection with or incidental to railroad transportation; and railway labor organizations, national in scope, which have been or may be organized in accordance with the provisions of the Railway Labor Act [45 U.S.C. 151 et seq.], and their State and National legislative committees and their general committees and their insurance departments and their local lodges and divisions, established pursuant to the constitution and bylaws of such organizations. The term \"employer\" shall not include any company by reason of its being engaged in the mining of coal, the supplying of coal to an employer where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities."],[0,"(b) The term \"carrier\" means a railroad subject to the jurisdiction of the Surface Transportation Board under part A of subtitle IV of title 49."],[0,"(c) The term \"company\" includes corporations, associations, and joint-stock companies."],[0,"(d) The term \"employee\" (except when used in phrases establishing a different meaning) means any individual who is or has been (i) in the service of one or more employers for compensation, or (ii) an employee representative. The term \"employee\" shall include an employee of a local lodge or division defined as an employer in subsection (a) only if he was in the service of a carrier on or after August 29, 1935. The term \"employee\" includes an officer of an employer."],[0,"The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"(e) An individual is in the service of an employer whether his service is rendered within or without the United States if (i) he is subject to the continuing authority of the employer to supervise and direct the manner of rendition of his service, or he is rendering professional or technical services and is integrated into the staff of the employer, or he is rendering, on the property used in the employer's operations, other personal services the rendition of which is integrated into the employer's operations, and (ii) he renders such service for compensation: Provided, however, That an individual shall be deemed to be in the service of an employer, other than a local lodge or division or a general committee of a railway-labor-organization employer, not conducting the principal part of its business in the United States only when he is rendering service to it in the United States; and an individual shall be deemed to be in the service of such a local lodge or division only if (1) all, or substantially all, the individuals constituting its membership are employees of an employer conducting the principal part of its business in the United States; or (2) the headquarters of such local lodge or division is located in the United States; and an individual shall be deemed to be in the service of such a general committee only if (1) he is representing a local lodge or division described in clauses (1) or (2) immediately above; or (2) all, or substantially all, the individuals represented by it are employees of an employer conducting the principal part of its business in the United States; or (3) he acts in the capacity of a general chairman or an assistant general chairman of a general committee which represents individuals rendering service in the United States to an employer, but in such case if his office or headquarters is not located in the United States and the individuals represented by such general committee are employees of an employer not conducting the principal part of its business in the United States, only such proportion of the remuneration for such service shall be regarded as compensation as the proportion which the mileage in the United States under the jurisdiction of such general committee bears to the total mileage under its jurisdiction, unless such mileage formula is inapplicable, in which case the Board may prescribe such other formula as it finds to be equitable, and if the application of such mileage formula, or such other formula as the Board may prescribe, would result in the compensation of the individual being less than 10 per centum of his remuneration for such service no part of such remuneration shall be regarded as compensation: Provided further, That an individual not a citizen or resident of the United States shall not be deemed to be in the service of an employer when rendering service outside the United States to an employer who is required under the laws applicable in the place where the service is rendered to employ therein, in whole or in part, citizens or residents thereof."],[0,"(f) The term \"employee representative\" means any officer or official representative of a railway labor organization other than a labor organization included in the term employer as defined in subsection (a) who before or after August 29, 1935, was in the service of an employer as defined in said subsection and who is duly authorized and designated to represent employees in accordance with the Railway Labor Act [45 U.S.C. 151 et seq.], and any individual who is regularly assigned to or regularly employed by such officer or official representative in connection with the duties of his office."],[0,"(g) The term \"employment\" means service performed as an employee. For the purposes of determining eligibility for and the amount of benefits and the amount of contributions due pursuant to this chapter, employment after June 30, 1940, in the service of a local lodge or division of a railway-labor-organization employer or as an employee representative shall be disregarded. For purposes of determining eligibility for and the amount of benefits and the amount of contributions due pursuant to this chapter, employment as a delegate to a national or international convention of a railway labor organization defined as an \"employer\", in subsection (a) of this section, shall be disregarded if the individual having such employment has not previously rendered service, other than as such a delegate, which may be included in his \"years of service\" for purposes of the Railroad Retirement Act [45 U.S.C. 231 et seq.]."],[0,"(h) The term \"registration period\" means, with respect to any employee, the period which begins with the first day for which such employee registers at an employment office in accordance with such regulations as the Board may prescribe, and ends with whichever is the earlier of (i) the thirteenth day thereafter, or (ii) the day immediately preceding the day for which he next registers at a different employment office; and thereafter each period which begins with the first day for which he next registers at an employment office after the end of his last preceding registration period which began with a day for which he registered at an employment office and ends with whichever is the earlier of (i) the thirteenth day thereafter, or (ii) the day immediately preceding the day for which he next registers at a different employment office."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/351?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§351. Definitions","tname":"Railroads","by":{"1":"3, 5"}},{"t":"usc","label":"45 U.S.C. § 352","url":"https://www.law.cornell.edu/uscode/text/45/352","subs":["(2020)","(c)(1)(A)"],"stext":{"head":"§352. Benefits","paras":[[0,"(a) Days for which benefits payable; determination of amount"],[0,"(1)(A) Payment of Unemployment Benefits.—"],[1,"(i) Generally.—Except as otherwise provided in this subparagraph, benefits shall be payable to any qualified employee for each day of unemployment in excess of 4 during any registration period within a period of continuing unemployment."],[1,"(ii) Waiting period for first registration period.—Benefits shall be payable to any qualified employee for each day of unemployment in excess of 7 during that employee's first registration period in a period of continuing unemployment if such period of continuing unemployment is the employee's initial period of continuing unemployment commencing in the benefit year."],[1,"(iii) Strikes.—"],[2,"(I) Initial 14-day waiting period.—If the Board finds that a qualified employee has a period of continuing unemployment that includes days of unemployment due to a stoppage of work because of a strike in the establishment, premises, or enterprise at which such employee was last employed, no benefits shall be payable for such employee's first 14 days of unemployment due to such stoppage of work."],[2,"(II) Subsequent days of unemployment.—For subsequent days of unemployment due to the same stoppage of work, benefits shall be payable as provided in clause (i) of this subparagraph."],[2,"(III) Subsequent periods of continuing unemployment.—If such period of continuing unemployment ends by reason of clause (v) but the stoppage of work continues, the waiting period established in clause (ii) shall apply to the employee's first registration period in a new period of continuing unemployment based upon the same stoppage of work."],[1,"(iv) Definition of period of continuing unemployment.—Except as limited by clause (v), for the purposes of this subparagraph, the term \"period of continuing unemployment\" means—"],[2,"(I) a single registration period that includes more than 4 days of unemployment;"],[2,"(II) a series of consecutive registration periods, each of which includes more than 4 days of unemployment; or"],[2,"(III) a series of successive registration periods, each of which includes more than 4 days of unemployment, if each succeeding registration period begins within 15 days after the last day of the immediately preceding registration period."],[1,"(v) Special rule regarding end of period.—For purposes of applying clause (ii), a period of continuing unemployment ends when an employee exhausts rights to unemployment benefits under subsection (c) of this section."],[1,"(vi) Limit on amount of benefits.—No benefits shall be payable to an otherwise eligible employee for any day of unemployment in a registration period where the total amount of the remuneration (as defined in section 351(j) of this title) payable or accruing to him for days within such registration period exceeds the amount of the base year monthly compensation base. For purposes of the preceding sentence, an employee's remuneration shall be deemed to include the gross amount of any remuneration that would have become payable to that employee but did not become payable because that employee was not ready or willing to perform suitable work available to that employee on any day within such registration period."],[0,"(B) Payment of Sickness Benefits.—"],[1,"(i) Generally.—Except as otherwise provided in this subparagraph, benefits shall be payable to any qualified employee for each day of sickness after the 4th consecutive day of sickness in a period of continuing sickness but excluding 4 days of sickness in any registration period in such period of continuing sickness."],[1,"(ii) Waiting period for first registration period.—Benefits shall be payable to any qualified employee for each day of sickness in excess of 7 during that employee's first registration period in a period of continuing sickness if such period of continuing sickness is the employee's initial period of continuing sickness commencing in the benefit year. For the purposes of this clause, the first registration period in a period of continuing sickness is that registration period that first begins with 4 consecutive days of sickness and includes more than 4 days of sickness."],[1,"(iii) Definition of period of continuing sickness.—For the purposes of this subparagraph, a period of continuing sickness means—"],[2,"(I) a period of consecutive days of sickness, whether from 1 or more causes; or"],[2,"(II) a period of successive days of sickness due to a single cause without interruption of more than 90 consecutive days which are not days of sickness."],[1,"(iv) Special rule regarding end of period.—For purposes of applying clause (ii), a period of continuing sickness ends when an employee exhausts rights to sickness benefits under subsection (c) of this section."],[0,"(2) The daily benefit rate with respect to any such employee for such day of unemployment or sickness shall be in an amount equal to 60 per centum of the daily rate of compensation for the employee's last employment in which he engaged for an employer in the base year, but not less than $12.70: Provided, however, That for registration periods beginning after June 30, 1975, but before July 1, 1976, such amount shall not exceed $24 per day of such unemployment or sickness, that for registration periods beginning after June 30, 1976, but before July 1, 1988, such amount shall not exceed $25 per day of such unemployment or sickness, that for registration periods beginning after June 30, 1988, but before July 1, 1989, such amount shall not exceed $30 per day of unemployment or sickness, and that for registration periods beginning after June 30, 1989, such amount shall not exceed the maximum daily benefit rate provided in paragraph (3) of this subsection. The daily rate of compensation referred to in this paragraph shall be determined by the Board on the basis of information furnished to the Board by the employee, his employer, or both."],[0,"(3) The maximum daily benefit rate computed by the Board under section 362(r)(2) of this title shall be the product of the monthly compensation base, as computed under section 351(i)(2) of this title for the base year immediately preceding the beginning of the benefit year, multiplied by 5 percent. If the maximum daily benefit rate so computed is not a multiple of $1, it shall be rounded down to the nearest multiple of $1."],[0,"(4) In computing benefits to be paid, days of unemployment shall not be combined with days of sickness in the same registration period."],[0,"(5)(A) Notwithstanding paragraph (3), subsection (c)(1)(B), and any other limitation on total benefits in this chapter, for registration periods beginning on or after April 1, 2020, but on or before July 31, 2020, and for registration periods beginning after December 26, 2020, but on or before September 6, 2021, a recovery benefit shall be payable to a qualified employee with respect to any registration period in which the employee received unemployment benefits under paragraph (1)(A), and in any registration period in which the employee did not receive unemployment benefits due to the limitation in subsection (c)(1)(B) or due to reaching the maximum number of days of benefits in the benefit year beginning July 1, 2019, or July 1, 2020, or July 1, 2021, under subsection (c)(1)(A). No recovery benefits shall be payable under this section upon the exhaustion of the funds appropriated under subparagraph (B) for payment of benefits under this subparagraph. For registration periods beginning on or after April 1, 2020, but on or before July 31, 2020, the recovery benefit payable under this subparagraph shall be in the amount of $1,200. For registration periods beginning after December 26, 2020, but on or before September 6, 2021, the recovery benefit payable under this subparagraph shall be in the amount of $600."],[0,"(B) Out of any funds in the Treasury not otherwise appropriated, there are appropriated $425,000,000 to cover the cost of recovery benefits provided under subparagraph (A), to remain available until expended."],[0,"(b) Time of payments"],[0,"The benefits provided for in this section shall be paid to an employee at such reasonable intervals as the Board may prescribe."],[0,"(c) Maximum number of days for benefits"],[0,"(1) Normal benefits"],[0,"(A) Generally"],[2,"The maximum number of days of unemployment within a benefit year for which benefits may be paid to an employee shall be 130, and the maximum number of days of sickness within a benefit year for which benefits may be paid to an employee shall be 130."],[0,"(B) Limitation"],[2,"The total amount of benefits that may be paid to an employee for days of unemployment within a benefit year shall in no case exceed the employee's compensation in the base year; and the total amount of benefits that may be paid to an employee for days of sickness within a benefit year shall in no case exceed the employee's compensation in the base year, except that notwithstanding section 351(i) of this title, in determining the employee's compensation in the base year for the purpose of this sentence, any money remuneration paid to the employee for services rendered as an employee shall be taken into account that is not in excess of an amount that bears the same ratio to $775 as the monthly compensation base for that year as computed under section 351(i) of this title bears to $600."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/352?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§352. Benefits","tname":"Railroads","by":{"1":"3, 3"}},{"t":"usc","label":"45 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/45/355","subs":["(b)","(c)","(c)(1)","(c)(2)","(c)(3)","(c)(4)","(c)(5)","(d)","(g)"],"stext":{"head":"§355. Claims for benefits","paras":[[0,"(a) Publication of Board's regulations"],[0,"Claims for benefits and appeals from determinations with respect thereto shall be made in accordance with such regulations as the Board shall prescribe. Each employer shall post and maintain, in places readily accessible to employees in his service, such printed statements concerning such regulations as the Board supplies to him for such purpose, and shall keep available to his employees copies of such printed statements. Such printed statements shall be supplied by the Board to each employer without cost to him."],[0,"(b) Findings, hearings, investigations, etc., by Board"],[0,"The Board is authorized and directed to make findings of fact with respect to any claim for benefits and to make decisions as to the right of any claimant to benefits. The Board is further authorized to hold such hearings, to conduct such investigations and other proceedings, and to establish, by regulations or otherwise, such procedures as it may deem necessary or proper for the determination of a right to benefits. When a claim for benefits is filed with the Board, the Board shall provide notice of such claim to the claimant's base-year employer or employers and afford such employer or employers an opportunity to submit information relevant to the claim before making an initial determination on the claim. When the Board initially determines to pay benefits to a claimant under this chapter, the Board shall provide notice of such determination to the claimant's base-year employer or employers."],[0,"(c) Hearing and review of decisions on claims"],[0,"(1) Each qualified employee whose claim for benefits has been denied in whole or in part upon an initial determination with respect thereto upon a basis other than one which is reviewable pursuant to one of the succeeding paragraphs of this subsection, shall be granted an opportunity for a fair hearing thereon before a referee or such other reviewing body as the Board may establish or assign thereto. In any such case the Board or the person or reviewing body so established or assigned shall, by publication or otherwise, notify all parties properly interested of their right to participate in the hearing and of the time and place of the hearing."],[0,"(2) Any claimant whose claim for benefits has been denied in an initial determination with respect thereto upon the basis of his not being a qualified employee, and any claimant who contends that under an initial determination of his claim he has been awarded benefits at less than the proper rate, may appeal to the Board for the review of such determination. Thereupon the Board shall review the determination and for such review may designate one of its officers or employees to receive evidence and to report to the Board thereon together with recommendations. In any such case the Board or the person so designated shall, by publication or otherwise, notify all parties properly interested of their right to participate in the proceeding and, if a hearing is to be held, of the time and place of the hearing. At the request of any party properly interested the Board shall provide for a hearing, and may provide for a hearing on its own motion. The Board shall prescribe regulations governing the appeals provided for in this paragraph and for decisions upon such appeal."],[0,"(3) Any base-year employer of a claimant whose claim for benefits has been granted in whole or in part, either in an initial determination with respect thereto or in a determination after a hearing pursuant to paragraph (1), and who contends that the determination is erroneous for a reason or reasons other than a reason that is reviewable under paragraph (4), may appeal to the Board for review of such determination. Despite such an appeal, the benefits awarded shall be paid to such claimant, subject to recovery by the Board if and to the extent found on the appeal to have been erroneously awarded. The Board shall take such action as is appropriate to recover the amount of such benefits including if feasible adjustment in subsequent payments pursuant to the first two paragraphs of section 352(d) of this title. Upon an appeal, the Board shall review the determination appealed from and for such review may designate one of its officers or employees to receive evidence and report to the Board thereof together with recommendations. In any such case the Board or the person so designated shall, by publication or otherwise, notify all parties properly interested of their right to participate in the proceeding and, if a hearing is to be held, of the time and place of the hearing. At the request of any party properly interested the Board shall provide for a hearing, and may provide for a hearing on its own motion. The Board shall prescribe regulations governing the appeals provided for in this paragraph and for decisions upon such appeal."],[0,"(4) In any case in which benefits are awarded to a claimant in whole or in part upon the basis of pay earned in the service of a person or company found by the Board to be an employer as defined in this chapter but which denies that it is such an employer, such benefits awarded on such basis shall be paid to such claimant subject to a right of recovery of such benefits. The Board shall thereupon designate one of its officers or employees to receive evidence and to report to the Board on whether such benefits should be repaid. The Board may also designate one of its officers or employees to receive evidence and report to the Board whether or not any person or company is entitled to a refund of contributions or should be required to pay contributions under this chapter, regardless of whether or not any claims for benefits will have been filed upon the basis of service in the employ of such person or company, and shall follow such procedure if contributions are assessed and payment is refused or payment is made and a refund claimed upon the basis that such person or company is or will not have been liable for such contributions. In any such case the Board or the person so designated shall, by publication or otherwise, notify all parties properly interested of their right to participate in the proceeding and, if a hearing is to be held, of the time and place of the hearing. At the request of any party properly interested the Board shall provide for a hearing, and may provide for a hearing on its own motion. The Board shall prescribe regulations governing the proceedings provided for in this paragraph and for decisions upon such proceedings."],[0,"(5) Final decision of the Board in the cases provided for in the preceding three paragraphs shall be communicated to the claimant and to the other interested parties within fifteen days after it is made. Any properly interested party notified, as hereinabove provided, of his right to participate in the proceedings may obtain a review of any such decision by which he claims to be aggrieved or the determination of any issue therein in the manner provided in subsection (f) of this section with respect to the review of the Board's decisions upon claims for benefits and subject to all provisions of law applicable to the review of such decisions. Subject only to such review, the decision of the Board upon all issues determined in such decision shall be final and conclusive for all purposes and shall conclusively establish all rights and obligations, arising under this chapter, of every party notified as hereinabove provided of his right to participate in the proceedings."],[0,"(6) For purposes of this subsection and subsections (d) and (f), any base-year employer of the claimant is a properly interested party."],[0,"(7) Any issue determinable pursuant to this subsection and subsection (f) of this section shall not be determined in any manner other than pursuant to this subsection and subsection (f)."],[0,"(d) Decisions of reviewing bodies; review and finality"],[0,"The Board shall prescribe regulations governing the filing of cases with and the decision of cases by reviewing bodies, and the review of such decisions. The Board may provide for intermediate reviews of such decisions by such bodies as the Board may establish or assign thereto. The Board may (i) on its own motion review a decision of an intermediate reviewing body on the basis of the evidence previously submitted in such case, and may direct the taking of additional evidence, or (ii) permit such parties as it finds properly interested in the proceedings to take appeals to the Board. Unless a review or an appeal is had pursuant to this subsection, the decision of an intermediate reviewing body shall, subject to such regulations as the Board may prescribe, be deemed to be the final decision of the Board."],[0,"(e) Application of rules of evidence in law and equity; notice of findings"],[0,"In any proceeding other than a court proceeding, the rules of evidence prevailing in courts of law or equity shall not be controlling, but a full and complete record shall be kept of all proceedings and testimony, and the Board's final determination, together with its findings of fact and conclusions of law in connection therewith, shall be communicated to the parties within fifteen days after the date of such final determination."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/355?type=usc&year=mostrecent&link-type=html"},"op":12,"ar":1,"head":"§355. Claims for benefits","tname":"Railroads","by":{"1":"6, 6, 21, 30, 44, 21, 30, 44, 21, 30, 44, 21, 21, 5, 5, 5, 5, 5, 5","2":"passim"}},{"t":"usc","label":"45 U.S.C. § 358","url":"https://www.law.cornell.edu/uscode/text/45/358","by":{"1":"5"}},{"t":"usc","label":"45 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/45/151","by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 1395oo","url":"https://www.law.cornell.edu/uscode/text/42/1395oo","subs":["(a)(1)(A)(i)"],"stext":{"head":"§1395oo. Provider Reimbursement Review Board","paras":[[0,"(a) Establishment"],[0,"Any provider of services which has filed a required cost report within the time specified in regulations may obtain a hearing with respect to such cost report by a Provider Reimbursement Review Board (hereinafter referred to as the \"Board\") which shall be established by the Secretary in accordance with subsection (h) and (except as provided in subsection (g)(2)) any hospital which receives payments in amounts computed under subsection (b) or (d) of section 1395ww of this title and which has submitted such reports within such time as the Secretary may require in order to make payment under such section may obtain a hearing with respect to such payment by the Board, if—"],[1,"(1) such provider—"],[2,"(A)(i) is dissatisfied with a final determination of the organization serving as its fiscal intermediary pursuant to section 1395h of this title as to the amount of total program reimbursement due the provider for the items and services furnished to individuals for which payment may be made under this subchapter for the period covered by such report, or"],[2,"(ii) is dissatisfied with a final determination of the Secretary as to the amount of the payment under subsection (b) or (d) of section 1395ww of this title,"],[2,"(B) has not received such final determination from such intermediary on a timely basis after filing such report, where such report complied with the rules and regulations of the Secretary relating to such report, or"],[2,"(C) has not received such final determination on a timely basis after filing a supplementary cost report, where such cost report did not so comply and such supplementary cost report did so comply,"],[1,"(2) the amount in controversy is $10,000 or more, and"],[1,"(3) such provider files a request for a hearing within 180 days after notice of the intermediary's final determination under paragraph (1)(A)(i), or with respect to appeals under paragraph (1)(A)(ii), 180 days after notice of the Secretary's final determination, or with respect to appeals pursuant to paragraph (1) (B) or (C), within 180 days after notice of such determination would have been received if such determination had been made on a timely basis."],[0,"(b) Appeals by groups"],[0,"The provisions of subsection (a) shall apply to any group of providers of services if each provider of services in such group would, upon the filing of an appeal (but without regard to the $10,000 limitation), be entitled to such a hearing, but only if the matters in controversy involve a common question of fact or interpretation of law or regulations and the amount in controversy is, in the aggregate, $50,000 or more."],[0,"(c) Right to counsel; rules of evidence"],[0,"At such hearing, the provider of services shall have the right to be represented by counsel, to introduce evidence, and to examine and cross-examine witnesses. Evidence may be received at any such hearing even though inadmissible under rules of evidence applicable to court procedure."],[0,"(d) Decisions of Board"],[0,"A decision by the Board shall be based upon the record made at such hearing, which shall include the evidence considered by the intermediary and such other evidence as may be obtained or received by the Board, and shall be supported by substantial evidence when the record is viewed as a whole. The Board shall have the power to affirm, modify, or reverse a final determination of the fiscal intermediary with respect to a cost report and to make any other revisions on matters covered by such cost report (including revisions adverse to the provider of services) even though such matters were not considered by the intermediary in making such final determination."],[0,"(e) Rules and regulations"],[0,"The Board shall have full power and authority to make rules and establish procedures, not inconsistent with the provisions of this subchapter or regulations of the Secretary, which are necessary or appropriate to carry out the provisions of this section. In the course of any hearing the Board may administer oaths and affirmations. The provisions of subsections (d) and (e) of section 405 of this title with respect to subpenas shall apply to the Board to the same extent as they apply to the Secretary with respect to subchapter II."],[0,"(f) Finality of decision; judicial review; determinations of Board authority; jurisdiction; venue; interest on amount in controversy"],[0,"(1) A decision of the Board shall be final unless the Secretary, on his own motion, and within 60 days after the provider of services is notified of the Board's decision, reverses, affirms, or modifies the Board's decision. Providers shall have the right to obtain judicial review of any final decision of the Board, or of any reversal, affirmance, or modification by the Secretary, by a civil action commenced within 60 days of the date on which notice of any final decision by the Board or of any reversal, affirmance, or modification by the Secretary is received. Providers shall also have the right to obtain judicial review of any action of the fiscal intermediary which involves a question of law or regulations relevant to the matters in controversy whenever the Board determines (on its own motion or at the request of a provider of services as described in the following sentence) that it is without authority to decide the question, by a civil action commenced within sixty days of the date on which notification of such determination is received. If a provider of services may obtain a hearing under subsection (a) and has filed a request for such a hearing, such provider may file a request for a determination by the Board of its authority to decide the question of law or regulations relevant to the matters in controversy (accompanied by such documents and materials as the Board shall require for purposes of rendering such determination). The Board shall render such determination in writing within thirty days after the Board receives the request and such accompanying documents and materials, and the determination shall be considered a final decision and not subject to review by the Secretary. If the Board fails to render such determination within such period, the provider may bring a civil action (within sixty days of the end of such period) with respect to the matter in controversy contained in such request for a hearing. Such action shall be brought in the district court of the United States for the judicial district in which the provider is located (or, in an action brought jointly by several providers, the judicial district in which the greatest number of such providers are located) or in the District Court for the District of Columbia and shall be tried pursuant to the applicable provisions under chapter 7 of title 5 notwithstanding any other provisions in section 405 of this title. Any appeal to the Board or action for judicial review by providers which are under common ownership or control or which have obtained a hearing under subsection (b) must be brought by such providers as a group with respect to any matter involving an issue common to such providers."],[0,"(2) Where a provider seeks judicial review pursuant to paragraph (1), the amount in controversy shall be subject to annual interest beginning on the first day of the first month beginning after the 180-day period as determined pursuant to subsection (a)(3) and equal to the rate of interest on obligations issued for purchase by the Federal Hospital Insurance Trust Fund for the month in which the civil action authorized under paragraph (1) is commenced, to be awarded by the reviewing court in favor of the prevailing party."],[0,"(3) No interest awarded pursuant to paragraph (2) shall be deemed income or cost for the purposes of determining reimbursement due providers under this chapter."],[0,"(g) Certain findings not reviewable"],[0,"(1) The finding of a fiscal intermediary that no payment may be made under this subchapter for any expenses incurred for items or services furnished to an individual because such items or services are listed in section 1395y of this title shall not be reviewed by the Board, or by any court pursuant to an action brought under subsection (f)."],[0,"(2) The determinations and other decisions described in section 1395ww(d)(7) of this title shall not be reviewed by the Board or by any court pursuant to an action brought under subsection (f) or otherwise."],[0,"(h) Composition and compensation"],[0,"The Board shall be composed of five members appointed by the Secretary without regard to the provisions of title 5 governing appointments in the competitive services. Two of such members shall be representative of providers of services. All of the members of the Board shall be persons knowledgeable in the field of payment of providers of services, and at least one of them shall be a certified public accountant. Members of the Board shall be entitled to receive compensation at rates fixed by the Secretary, but not exceeding the rate specified (at the time the service involved is rendered by such members) for grade GS–18 in section 5332 of title 5. The term of office shall be three years, except that the Secretary shall appoint the initial members of the Board for shorter terms to the extent necessary to permit staggered terms of office."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395oo?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1395oo. Provider Reimbursement Review Board","tname":"The Public Health and Welfare","by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 2252","url":"https://www.law.cornell.edu/uscode/text/18/2252","subs":["(b)(2)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 2259","url":"https://www.law.cornell.edu/uscode/text/18/2259","subs":["(b)(3)(F)(2012)"],"by":{"1":"25, 26"}},{"t":"usc","label":"31 U.S.C. § 3526","url":"https://www.law.cornell.edu/uscode/text/31/3526","by":{"1":"23"}},{"t":"usc","label":"31 U.S.C. § 3530","url":"https://www.law.cornell.edu/uscode/text/31/3530","by":{"1":"23"}},{"t":"case","label":"Berry v. Dep’t of Labor","cite":"832 F.3d 627","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/832/627/","sum":"Describing denial of reopening in the face of new evidence as a “concrete injury” to the claimant.","sumSrc":"brief:2","by":{"2":"4"}},{"t":"case","label":"Cappadora v. Celebrezze","cite":"356 F.2d 1","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/356/1/","by":{"2":"21"}},{"t":"case","label":"FTC v. Mandel Brothers, Inc.","cite":"359 U.S. 385","y":1959,"id":"1958/234","sc":1,"sum":"The Commission did not abuse its discretion by making its order apply to all six categories.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Jama v. Immigration & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"MacFarland v. Elverson","cite":"32 App. D.C. 81","y":1908,"url":"https://www.courtlistener.com/c/App.%20D.C./32/81/","by":{"2":"13"}},{"t":"case","label":"Mims v. Arrow Fin. Servs., LLC","cite":"565 U.S. 368","y":2012,"id":"2011/10-1195","sc":1,"sum":"The Court held that the Telephone Consumer Protection Act does not strip federal courts of the ability to hear cases that would normally be brought in state courts.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Mulloy v. United States","cite":"398 U.S. 410","y":1970,"id":"1969/655","sc":1,"sum":"Where a registrant makes nonfrivolous allegations of facts not previously considered by his board, that, if true, would be sufficient under the regulations to warrant granting a reclassification, the board must reopen the classification, unless the truth of the new allegations is conclusively refuted by other reliable information in registrant's file, thus affording the registrant an administrative appeal from an …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"140 S. Ct. 1492","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Service v. Dulles","cite":"354 U.S. 363","y":1957,"id":"1956/407","sc":1,"sum":"Petitioner's discharge was invalid, because it violated Regulations of the Department of State which were binding on the Secretary; and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Thole v. U.S. Bank N.A.","cite":"140 S. Ct. 1615","y":2020,"id":"2019/17-1712","sc":1,"sum":"The Court held that an ERISA plan participant lacks judicial standing to seek injunctive relief or restoration of plan losses caused by fiduciary breach if he cannot demonstrate individual financial loss or the imminent risk thereof.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"United States v. Palmer","cite":"16 U.S. 610","y":1818,"id":"scdb/1818-038","sc":1,"sum":"A robbcry committed on the high seas, although such robbery if com., milled on land would not by the lav s of the United Surtes bo punishable with death, is piracy under the 8th section of the act of 1700 ch. 36, (ix) for the punishment of certain crimes against the United Slates; and the circuit court have jurisdiction thereof.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Vill. of Barrington v. Surface Transp. Bd.","cite":"758 F.3d 326","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/758/326/","by":{"2":"21"}},{"t":"case","label":"Virginia v. Browner","cite":"80 F.3d 869","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/80/869/","by":{"2":"13"}},{"t":"reg","label":"20 C.F.R. § 260.9","url":"https://www.ecfr.gov/current/title-20/section-260.9","subs":["(a)"],"by":{"2":"19"}},{"t":"usc","label":"15 U.S.C. § 79k","url":"https://www.law.cornell.edu/uscode/text/15/79k","subs":["(b)(1952)"],"by":{"2":"5"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(b)(3)"],"by":{"2":"15"}}]};